#pragma once
#include "chat-effect-checks.hpp"
namespace oto::testing {
inline constexpr unsigned fullFlags[]={8,16,32,64,256,512,1024,2048,4096,8192,32768,65536,32|64,131072};
inline QByteArray fullFFZCatalog(){QJsonArray list;for(int i=0;i<14;++i)list.append(QJsonObject{{"name",QString("F%1").arg(i)},{"modifier",true},{"modifier_flags",int(fullFlags[i]|1)},{"urls",QJsonObject{{"2","//cdn.frankerfacez.com/emote/720510/2"}}}});return QJsonDocument(QJsonObject{{"default_sets",QJsonArray{1}},{"sets",QJsonObject{{"1",QJsonObject{{"emoticons",list}}}}}}).toJson();}
inline events::ChatEvent fullFFZMessage(){events::ChatEvent m{{"12345","FFZ"},{}};for(int i=0;i<14;++i){m.fragments.push_back({"Kappa","25",false});m.fragments.push_back({" F"+std::to_string(i)+" ",{},false});}for(const auto &f:m.fragments)m.message+=f.text;return m;}
inline std::shared_ptr<chat::EmoteCache> fullFFZCache(std::shared_ptr<visual::VisualEngine> visual){auto m=std::make_shared<chat::EmoteCache>(visual,[](QString url,std::function<void(twitch::HttpReply)> done){done(url.endsWith("/set/global")?twitch::HttpReply{200,fullFFZCatalog(),false}:twitch::HttpReply{404,{},false});});m->ensureChannel("123");m->ingest(layerBase,effectPng());return m;}
inline void checkFullFFZ(std::shared_ptr<visual::VisualEngine> visual){const auto check=[](bool v,const char *s){if(!v)throw std::runtime_error(s);};auto cache=fullFFZCache(visual);const auto tokens=cache->tokens(fullFFZMessage(),true);int n=0;for(const auto &t:tokens)if(!t.url.isEmpty()){check(t.effects==chat::ffzEffects(fullFlags[n++]),"FFZ complete metadata mapping");}check(n==14,"FFZ complete token count");
 for(const auto flags:fullFlags){const auto effect=chat::ffzEffects(flags);const auto extent=chat::emoteExtent(effect);for(int ms=0;ms<6000;ms+=7){const auto s=chat::sampleEmote(effect,true,ms);check(std::isfinite(s.scaleX) && std::isfinite(s.angle) && std::abs(s.scaleX)<=1.201 && std::abs(s.scaleY)<=1.201,"FFZ sampling invalid");check(std::abs(s.shiftX)*2+std::abs(s.scaleX)<=extent[0]+.001 && std::abs(s.shiftY)*2+std::abs(s.scaleY)<=extent[1]+.001,"FFZ envelope clips");}const auto frozen=chat::sampleEmote(effect,false,1500);check(frozen.scaleX==1 && frozen.scaleY==1 && frozen.shiftX==0 && frozen.shiftY==0 && frozen.slide==0,"FFZ OFF retains motion");}
 events::EventEngine e;e.start();const auto event=e.process({"ffz-full","123",std::chrono::system_clock::now(),events::EventOrigin::Preview,fullFFZMessage()});check(bool(event),"FFZ full event");const sources::ChatView view{{events::EventOrigin::Preview,"123"},1,{{event.event,{},1,1}}};for(bool horizontal:{false,true}){sources::ChatSettings settings;settings.layout=horizontal?sources::ChatLayout::Horizontal:sources::ChatLayout::Vertical;settings.width=320;settings.height=100;const auto frame=sources::prepareChatFrame(*visual,settings,view,{},visual::MotionClock::now(),false,cache.get());check(frame->rows.back().emotes.size()==14,"FFZ full compact loses emotes");for(const auto &em:frame->rows.back().emotes)check(em.media==frame->rows.back().emotes.front().media,"FFZ duplicate images");}cache->stop();e.stop();
}
}
